DECLARE @RunDateClean NVARCHAR(8) = REPLACE(CONVERT(NVARCHAR(10), GETDATE(), 120), '-', '');
DECLARE @SQL NVARCHAR(MAX) = N'
SELECT 
    (SELECT COUNT(*) FROM staging.Silver_Wells) AS SilverRowCount,
    (SELECT COUNT(*) FROM staging.Silver_Wells) AS SourceRowCount,
    (SELECT COUNT(*) FROM dbo.quarantine_' + @RunDateClean + N') AS QuarantineRowCount';
EXEC sp_executesql @SQL;
